"""Helper to provide eight information cards for each media tool.
Each tool slug maps to a list of eight dictionaries with keys:
    icon (HTML/SVG), title, description.
"""

def _make_svg(path_d: str, fill="none", stroke="currentColor", stroke_width="2") -> str:
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" '
        f'fill="{fill}" stroke="{stroke}" stroke-width="{stroke_width}" stroke-linecap="round" '
        f'stroke-linejoin="round">{path_d}</svg>'
    )

