def get_tool_cards(tool_slug: str):
    """Return a list of eight rich card dicts for the given tool slug.
    Each card has 'icon' (SVG markup), 'title', and 'description'.
    """
    clean_slug = (tool_slug or "").strip().lower().replace("_", "-")
    canonical_slug = SLUG_ALIASES.get(tool_slug, SLUG_ALIASES.get(clean_slug, clean_slug))

    if canonical_slug in CARDS_DATA:
        return CARDS_DATA[canonical_slug]

    # Generate meaningful fallback cards for any unlisted slug
    readable_name = clean_slug.replace("-", " ").title()
    return _default_cards(readable_name, clean_slug.replace("-", " "))
